pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    bytes32 constant PROPOSER_ROLE = keccak256("PROPOSER_ROLE");
    bytes32 constant TIMELOCK_ADMIN_ROLE = keccak256("TIMELOCK_ADMIN_ROLE");

    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // Before granting, the account must NOT have the role.
        bool before = c.hasRole(PROPOSER_ROLE, actor);
        // Admin (deployer/test contract) grants PROPOSER_ROLE to the fuzzed actor.
        vm.prank(c.getRoleMemberless());
        c.grantRole(PROPOSER_ROLE, actor);
        bool after = c.hasRole(PROPOSER_ROLE, actor);
        // General rule: after grantRole, hasRole must be true; before, it was false.
        assertTrue(!before && after);
    }
}

