pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role, address actor) public {
        // Admissible domain: the whole space; any account that was never granted `role`
        // (the constructor grants only PROPOSER/EXECUTOR/TIMELOCK roles to nobody but
        // the deployer and address(this) for TIMELOCK_ADMIN_ROLE — renounce still clears it).
        // Renounce a role that was never granted: in the reference this is a no-op
        // (hasRole is already false) and the account must NOT hold the role afterwards.
        vm.prank(actor);
        c.renounceRole(role, actor);

        // General rule: an account that never held the role (renounce of nothing)
        // must not have the role. P: hasRole stays false. M: negated lookup -> true.
        assertTrue(!c.hasRole(role, actor));
    }
}

